import { zeroSteps, zeroSources } from './zero.js';
import { renderLessonDemo } from './lesson-demo.js';

export function plainFlow(items, escape) {
  return `<ol class="plain-flow">${items.map(([title,detail],i)=>`<li><span class="flow-order">${i+1}</span><strong>${escape(title)}</strong><span>${escape(detail)}</span></li>`).join('')}</ol>`;
}

function termCards(terms, inline, escape) {
  return `<dl class="term-cards">${terms.map(t=>`<div><dt>${escape(t.term)}</dt><dd>${inline(t.meaning)}</dd></div>`).join('')}</dl>`;
}

export function renderChapterBridge(c, {inline,escape}) {
  if (!c.bridge) return '';
  const b=c.bridge;
  return `${renderLessonDemo('chapter',c.id)}<section class="chapter-bridge" id="chapter-bridge"><div class="eyebrow">先接上前一步，再学新东西</div><p><b>你已经知道：</b>${inline(b.known)}</p><p><b>接着遇到的问题：</b>${inline(b.problem)}</p><p><b>本章的办法：</b>${inline(b.idea)}</p><h2>这章先认识这几个词</h2>${termCards(b.terms,inline,escape)}<p class="takeaway">${inline(b.takeaway)}</p></section>`;
}

export function renderZeroPage(stepId, {inline,escape,codeBlock}) {
  const index=Math.max(0,zeroSteps.findIndex((s,i)=>s.id===stepId||String(i+1)===stepId));
  const s=zeroSteps[index];
  const reviewParagraphs=s.id==='deps'?s.paragraphs.slice(0,-1):s.paragraphs;
  const projectBridge=s.id==='deps'?`<aside class="zero-goal"><b>回到 LoongSuite：</b><p>${inline(s.paragraphs.at(-1).replace('回到 LoongSuite：',''))}</p></aside>`:'';
  return `<div class="zero-layout"><header class="zero-header"><div class="eyebrow">从零开始 / 不需要先认识探针术语</div><h1>先理解为什么，<br>再看代码怎么做。</h1><p>从一次查房间开始：先看程序做了什么，再认代码里的词。图与代码用来解释过程；浏览器不会执行 Go。</p></header><nav class="zero-nav" aria-label="从零开始的七个步骤">${zeroSteps.map((x,i)=>`<a href="#/start/${i+1}" ${i===index?'aria-current="step" class="active"':''}><span>${String(i+1).padStart(2,'0')}</span>${escape(x.title)}</a>`).join('')}</nav><article class="zero-lesson"><div class="eyebrow">第 ${index+1} / ${zeroSteps.length} 步 · ${escape(s.title)}</div><h2>${escape(s.question)}</h2><aside class="zero-goal"><p><b>这页学会一件事：</b>${inline(s.goal)}</p><p><b>从这里接上：</b>${inline(s.beforeYouRead)}</p></aside>${renderLessonDemo('zero',s.id)}${projectBridge}<details class="zero-review"><summary>需要文字复习？查看解释、术语和代码对照</summary><div>${reviewParagraphs.map(p=>`<p>${inline(p)}</p>`).join('')}<section class="zero-terms"><h3>刚出现的词，在这里解释</h3>${termCards(s.terms,inline,escape)}</section><figure class="plain-figure">${plainFlow(s.flow,escape)}<figcaption>按箭头顺序理解；这是一张教学简图。</figcaption></figure><section class="zero-example"><h3>${escape(s.before.label)}</h3>${codeBlock(s.before.code,s.before.language||'go')}<h3>${escape(s.after.label)}</h3>${codeBlock(s.after.code,s.after.language||'go')}<p class="example-caption">${inline(s.caption)}</p></section></div></details><section class="self-explain"><div class="eyebrow">停一下，用自己的话说</div><h3>${escape(s.check.question)}</h3><details><summary>展开参考解释</summary><p>${inline(s.check.answer)}</p></details></section><aside class="takeaway"><b>这一步只带走一句话：</b>${inline(s.takeaway)}</aside>${s.destination?`<p><a class="btn" href="${escape(s.destination.href)}">${escape(s.destination.label)}</a></p>`:''}<nav class="prev-next" aria-label="入门步骤切换">${index?`<a href="#/start/${index}"><small>← 上一步</small>${escape(zeroSteps[index-1].title)}</a>`:'<a href="#/"><small>← 查看全景</small>回到学习路线</a>'}${index<zeroSteps.length-1?`<a href="#/start/${index+2}"><small>下一步 →</small>${escape(zeroSteps[index+1].title)}</a>`:'<a href="#/learn/orientation"><small>开始正式课程 →</small>跟随一次构建读懂源码</a>'}</nav><details class="zero-references"><summary>本组讲解的来源</summary><ul>${zeroSources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a></li>`).join('')}</ul></details></article></div>`;
}

const sourcePhases=[
  {label:'看清项目',href:'go-mod',ids:['go-mod']},
  {label:'启动构建',href:'cli',ids:['cli']},
  {label:'准备依赖和规则',href:'preprocess',ids:['preprocess','deps','rule-load','rule-model','bundle','rule-json']},
  {label:'接到编译工具',href:'toolexec',ids:['toolexec','match']},
  {label:'改写函数',href:'instrument',ids:['instrument','func-ast','trampoline','call-context','call-context-impl','hook-rule']},
  {label:'运行并记录',href:'otel-runtime',ids:['linkname','gls','otel-runtime','version-boundary']}
];

export function renderSourcePage(s, lesson, nodes, {inline,escape,codeBlock}) {
  const phase=sourcePhases.find(p=>p.ids.includes(s.id));
  const l=lesson;
  return `<header class="source-intro"><div class="eyebrow">源码地图 / 先讲问题，再读实现</div><h1>${escape(l.title)}</h1><p class="source-plain">${inline(l.plain)}</p><p><a class="btn light" href="#lesson-demo-source-${escape(s.id)}" data-scroll="lesson-demo-source-${escape(s.id)}">先看本页实例动画 ↓</a></p><p>第一次接触？<a href="#/start/1">从一个普通 Go 函数开始 →</a>${s.id==='deps'?'　也可先补 <a href="#/start/2">包和模块</a>、<a href="#/start/3">go.mod</a>、<a href="#/start/6">依赖为什么要补</a>。':''}</p></header><nav class="source-journey" aria-label="这个文件在整个流程的哪里">${sourcePhases.map((p,i)=>`<a href="#/source/${p.href}" class="${phase===p?'current':''}" ${phase===p?'aria-current="location"':''}><small>${i+1}</small>${escape(p.label)}</a>`).join('')}</nav><p class="diagram-caption">这是理解职责的顺序；“准备依赖和规则”内部会交替更新依赖与匹配，不是一条只走一次的直线。</p><details class="source-index"><summary>切换源码节点 · 共 ${nodes.length} 个 · 当前：${escape(s.title)}</summary><div class="source-index-body"><label for="source-filter">按函数、文件或职责筛选</label><input class="filter-input" id="source-filter" type="search" placeholder="例如：依赖、addDependency、hook"><nav class="source-list" aria-label="源码阅读路径">${nodes.map((x,i)=>`<button class="source-item ${x.id===s.id?'active':''}" data-source="${escape(x.id)}" aria-pressed="${x.id===s.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span>${escape(x.title)}<small>${escape(x.path)}</small></span></button>`).join('')}</nav><p class="empty source-no-results" hidden>没有匹配节点；试试“依赖”、hook 或函数名。</p></div></details><article class="source-detail source-lesson">${renderLessonDemo('source',s.id)}${s.id==='preprocess'?preprocessRealExample:''}<section class="why-box"><h2>先说为什么需要它</h2><p>${inline(l.why)}</p></section><section class="source-section"><h2>01 · 本页先认这些词</h2>${termCards(l.terms,inline,escape)}${l.prerequisites.length?`<p class="source-prerequisites">还不熟？${l.prerequisites.map(p=>`<a href="${escape(p.href)}">${escape(p.label)} →</a>`).join('　')}</p>`:''}</section>${s.id==='deps'?`<figure class="plain-figure"><h3>别把这三个角色混在一起</h3>${plainFlow([['你的业务项目','被加工：原本负责处理请求'],['otel 构建工具','加工者：准备依赖并改写编译输入'],['hook 和记录库','被接入业务产物：运行时真正记录']],escape)}<figcaption>工具能运行 ≠ 业务已经拥有它生成代码要用的库。第三个角色的代码也必须能被业务构建找到。</figcaption></figure>`:''}<section class="source-section"><h2>02 · 它拿到什么，交出什么</h2><div class="io-pair"><section><span>输入</span><p>${inline(l.input)}</p></section><section><span>输出 / 产生的变化</span><p>${inline(l.output)}</p></section></div></section><section class="source-section"><h2>03 · 用小例子拆开看</h2><ol class="explain-steps">${l.steps.map((step,i)=>`<li><div class="step-marker">${i+1}</div><div><h3>${escape(step.title)}</h3><p>${inline(step.explanation)}</p>${step.code?codeBlock(step.code,step.language||'text'):''}</div></li>`).join('')}</ol></section><section class="source-section"><h2>04 · 再把人话对上源码</h2><p class="source-path">${escape(s.path)}:${s.line} · ${escape(s.symbol)}</p><div class="source-annotations">${l.sourceNotes.map(n=>`<section><code>${escape(n.code)}</code><p>${inline(n.explanation)}</p></section>`).join('')}</div><details class="raw-source"><summary>我想看原始源码摘录（可稍后再读）</summary><p>摘录固定在 v1.15.0 / <code>cac4009</code>；保留上游行号。片段会截断，完整函数请打开来源。</p>${codeBlock(s.snippet||'请打开来源查看完整代码。','Go · 上游行号',false)}<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">打开这个函数的固定提交源码 ↗</a></details></section><section class="source-section"><h2>05 · 容易混淆的地方</h2><ul class="pitfalls">${l.pitfalls.map(p=>`<li>${inline(p)}</li>`).join('')}</ul></section><section class="self-explain"><div class="eyebrow">不背定义，用因果解释</div><h2>${escape(l.check.question)}</h2><details><summary>展开参考解释</summary><p>${inline(l.check.answer)}</p></details></section><div class="toolbar"><a class="btn" href="${escape(l.next.href)}">${escape(l.next.label)} →</a><a class="btn light" href="#/start/1">回到从零开始</a></div><p class="diagram-caption">源码摘录版权归上游作者，采用 Apache-2.0。讲解、简图与教学示例由本指南编写。<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">本页源码依据 ↗</a></p></article>`;
}

const preprocessRealExample=`<aside class="source-real-example"><h3>源码里的同类情况：给 GORM 加观察代码，为什么会多出 MySQL 包？</h3><p>假设业务原来使用匹配版本的 GORM 和 PostgreSQL，没有引用 MySQL driver。第一次匹配会选中 GORM 的 <code>Open</code> 规则。这个规则指向的 <code>pkg/rules/gorm/setup.go</code> 自己却引用了 <code>gorm.io/driver/mysql</code>，并访问 <code>Config.DbInfo</code>。</p><p>把 GORM 记录包加入构建以后，MySQL driver 也进入构建范围；第二次匹配才能对它应用“给 Config 增加 DbInfo 字段”的规则。这解释了为什么加入规则代码后还要重新匹配。第三次准备按最终结果再生成、同步；本例不保证第三次一定增加新模块。</p><p>上面的动画用两个教学自定义规则，把“第二次匹配又选出一个带记录包的规则”的情形拆得更明显。实际依赖取决于你的项目；当前实现固定两次匹配，没有循环到完全不再变化的检查。</p><p>这是基于固定源码推导的路径，没有在本页执行该数据库组合。对应源码：<a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/tool/data/rules/gorm.json" target="_blank" rel="noopener noreferrer">GORM 规则</a> · <a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/pkg/rules/gorm/setup.go#L106" target="_blank" rel="noopener noreferrer">记录包读取 DbInfo</a> · <a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/tool/preprocess/preprocess.go#L273" target="_blank" rel="noopener noreferrer">三轮的实际控制流</a></p></aside>`;
